message.content:
{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The rescue team gathers at the edge of the ruined city.",
      "visual_description": "A windswept ridge overlooks a shattered royal city at dusk. Mara unrolls a hand-drawn map across a broken stone while a small clockwork fox sniffs the air beside her.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 2,
      "caption": "An old lamp wakes and warns of danger ahead.",
      "visual_description": "A battered oil lamp sits on the stone, its single flame-eye blinking open. Mara leans close, brass compass swinging, as the lamp's glow paints her ink-stained coat.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The glass diver emerges from a roadside puddle.",
      "visual_description": "A figure in a clear diving helmet rises impossibly from a shallow rain puddle, coat shimmering with reflected city lights. The tin fox tilts its head, blue glass eyes glinting.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "They approach the broken castle gates.",
      "visual_description": "Massive iron gates hang half-torn from their hinges, carved with faded royal crests. Mara studies the threshold while the glass diver checks his helmet seals.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "Tattered royal banners flutter overhead.",
      "visual_description": "Long crimson banners trail like torn sails over an empty plaza. The tin fox darts between fallen banner-poles, its key-wind tail ticking softly.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 6,
      "caption": "A dozing official slumps in a forgotten booth.",
      "visual_description": "Inside a leaning toll booth, the sleeping tax collector snores on a ledger pillow, stamped papers stuck to his sleeves. The lamp's eye narrows in disapproval.",
      "characters": ["sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "The lamp warns of an armored patrol nearby.",
      "visual_description": "Down a moonlit alley, lantern light glints off distant breastplates. The oracle lamp dims its eye to a sliver while Mara presses against a cracked wall.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 8,
      "caption": "The glass diver slips through a shop window like water.",
      "visual_description": "A storefront pane ripples as the diver wades halfway through it, coat trailing reflections of broken streetlamps. The tin fox watches from the cobblestones.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "Rumors of a great winged beast echo over the rooftops.",
      "visual_description": "A vast shadow sweeps across smoke-streaked clouds above a cursed tower. Mara grips her compass tightly, ignoring the tempting silhouette, eyes fixed on her map.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "The cursed tower hums with trapped magic.",
      "visual_description": "A leaning black tower pulses with sickly green light through its arrow-slits. The tin fox circles it warily, gears clicking, while the glass diver studies its mirrored windows.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "Frightened faces peek from shuttered windows.",
      "visual_description": "Pale eyes glimmer behind cracked shutters along a narrow lane. Mara raises a calming hand; the lamp lifts its glow to show she means no harm.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "A magic door bars the way to the prisoner.",
      "visual_description": "A tall door carved with shifting silver runes blocks a vaulted corridor. The glass diver presses a gloved palm to its surface; the tin fox sits patiently, tail winding down.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "The lamp whispers the door's true name.",
      "visual_description": "Oracle lamp hovers near the runes, single eye flaring as letters rearrange themselves in its light. Mara copies the pattern into her notebook with a trembling pen.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 14,
      "caption": "The diver swims through a mirror into the locked chamber.",
      "visual_description": "A tall cracked mirror ripples like a pond; the glass diver leans inward, his helmet half-submerged in silver. Reflections of the ruined city bend around his coat.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "Inside, the dozing official is the captive they were sent for.",
      "visual_description": "A small cell of stamped papers and chains; the sleeping tax collector slumps against a wall, ledger still clutched. The glass diver lifts him gently, exasperated.",
      "characters": ["glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "Armored patrols thunder down the corridor behind them.",
      "visual_description": "Sparks fly from the magic door as it shudders. Mara waves the team onward through a side arch; the tin fox skitters ahead, key-tail spinning wildly.",
      "characters": ["mara_the_cartographer", "tin_fox", "glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "They race across the long bridge out of the city.",
      "visual_description": "A narrow stone bridge arcs over a foggy ravine, lit by the lamp's swinging glow. The diver carries the snoring official; Mara and the tin fox run just ahead.",
      "characters": ["mara_the_cartographer", "glass_diver", "sleeping_tax_collector", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far shore, the lamp dims and the fox curls to rest.",
      "visual_description": "Beyond the bridge, dawn light spills over a quiet meadow. Mara folds her map; the glass diver sets down the still-snoring official; the tin fox curls beside the dimming oracle lamp.",
      "characters": ["mara_the_cartographer", "glass_diver", "sleeping_tax_collector", "tin_fox", "oracle_lamp"]
    }
  ]
}

